def maliyet_df():
    return pd.DataFrame(MALIYET)


def progress_rows():
    out = []
    for it in MALIYET:
        gd = {'GES-1': it['g1'], 'GES-2': it['g2'], 'ORTAK': it['ort']}
        dom = max(gd, key=gd.get) if max(gd.values()) > 0 else 'ORTAK'
        out.append({
            'id': it['poz'], 'grp': dom, 'disc': it['disc'],
            'name': it['ad'], 'unit': it['birim'],
            'qty': float(it['g1']+it['g2']+it['ort']), 'up': float(it['bf']),
            'plan': 0.0, 'real': 0.0,
        })
    return out
